UPDATE account
SET display_name = CASE id
    WHEN '11111111-1111-1111-1111-111111110001' THEN '지구대 지휘관'
    WHEN '11111111-1111-1111-1111-111111110002' THEN '지구대 순찰차'
    WHEN '11111111-1111-1111-1111-111111110003' THEN '지구대 현장팀'
    WHEN '11111111-1111-1111-1111-111111110004' THEN '실종팀 지휘관'
    WHEN '11111111-1111-1111-1111-111111110005' THEN '실종팀 현장팀'
    WHEN '11111111-1111-1111-1111-111111110006' THEN '지원부대 지휘관'
    WHEN '11111111-1111-1111-1111-111111110007' THEN '지원부대 순찰차'
    WHEN '11111111-1111-1111-1111-111111110008' THEN '지원부대 현장팀'
    ELSE display_name
END,
updated_at = CURRENT_TIMESTAMP
WHERE id IN (
    '11111111-1111-1111-1111-111111110001',
    '11111111-1111-1111-1111-111111110002',
    '11111111-1111-1111-1111-111111110003',
    '11111111-1111-1111-1111-111111110004',
    '11111111-1111-1111-1111-111111110005',
    '11111111-1111-1111-1111-111111110006',
    '11111111-1111-1111-1111-111111110007',
    '11111111-1111-1111-1111-111111110008'
);

UPDATE police_phone
SET display_name = CASE id
    WHEN '00000000-0000-0000-0000-000000000201' THEN '지구대 지휘관 단말'
    WHEN '50000000-0000-0000-0000-000000000001' THEN '지구대 순찰차 단말'
    WHEN '00000000-0000-0000-0000-000000000101' THEN '지구대 현장팀 단말'
    WHEN '00000000-0000-0000-0000-000000000204' THEN '실종팀 지휘관 단말'
    WHEN '00000000-0000-0000-0000-000000000205' THEN '실종팀 현장팀 단말'
    WHEN '00000000-0000-0000-0000-000000000206' THEN '지원부대 지휘관 단말'
    WHEN '00000000-0000-0000-0000-000000000207' THEN '지원부대 순찰차 단말'
    WHEN '00000000-0000-0000-0000-000000000208' THEN '지원부대 현장팀 단말'
    ELSE display_name
END,
updated_at = CURRENT_TIMESTAMP
WHERE id IN (
    '00000000-0000-0000-0000-000000000201',
    '50000000-0000-0000-0000-000000000001',
    '00000000-0000-0000-0000-000000000101',
    '00000000-0000-0000-0000-000000000204',
    '00000000-0000-0000-0000-000000000205',
    '00000000-0000-0000-0000-000000000206',
    '00000000-0000-0000-0000-000000000207',
    '00000000-0000-0000-0000-000000000208'
);
